#[cfg(test)]
mod segment_file_count_probe {
    use super::*;
    use std::collections::BTreeMap;
    use std::time::Instant;
    use serde_json::json;

    fn verify_bundle(path: &Path, expected: &BTreeMap<String, Vec<u8>>) {
        let bytes = fs::read(path).unwrap();
        assert_eq!(&bytes[..8], b"LXPROBE1");
        let end = bytes.len() - 12;
        let table_len = u64::from_le_bytes(bytes[end..end + 8].try_into().unwrap()) as usize;
        let checksum = u32::from_le_bytes(bytes[end + 8..].try_into().unwrap());
        let table_bytes = &bytes[end - table_len..end];
        assert_eq!(crc32fast::hash(table_bytes), checksum);
        let table: Vec<(String, u64, u64, u32)> = serde_json::from_slice(table_bytes).unwrap();
        assert_eq!(table.len(), expected.len());
        for (name, offset, len, checksum) in table {
            let data = &bytes[offset as usize..(offset + len) as usize];
            assert_eq!(data, expected[&name]);
            assert_eq!(crc32fast::hash(data), checksum);
        }
    }

    #[test]
    #[ignore]
    fn compare_segment_file_count_publication() {
        for (blocks, rows_per_block) in [(128, 1), (128, 128), (512, 1024)] {
            let config = Config { blocks, warm_headers: 8192, rows_per_block, history_batch_blocks: 2048, segment_rows: 1_000_000, repeats: 1, route: Some(true), checkpoint_each_block: false, rich_headers: false };
            let (_, blocks) = fixture(&config);
            let rows: Vec<_> = blocks.into_iter().flatten().collect();
            let source = tempfile::tempdir().unwrap();
            let encoded = write_bundled_rows(source.path(), &rows).unwrap();
            let manifest = SegmentManifest {
                column_bundle: encoded.bundle,
                format_version: super::super::catalog::STORAGE_FORMAT_VERSION,
                segment_id: 1, generation: 0, kind: SegmentKind::Sealed,
                min_block: rows.first().map(|row| row.block_number),
                max_block: rows.last().map(|row| row.block_number),
                min_timestamp: rows.first().map(|row| row.timestamp),
                max_timestamp: rows.last().map(|row| row.timestamp),
                row_count: rows.len() as u64,
                canonical_rows_path: "canonical.bitmap".to_owned(),
                columns: encoded.columns, indexes: Vec::new(),
            };
            let files: BTreeMap<String, Vec<u8>> = BTreeMap::from([
                (BUNDLE_PATH.to_owned(), fs::read(source.path().join(BUNDLE_PATH)).unwrap()),
                ("canonical.bitmap".to_owned(), fs::read(source.path().join("canonical.bitmap")).unwrap()),
                ("segment.json".to_owned(), serde_json::to_vec(&manifest).unwrap()),
            ]);
            let catalog = vec![0u8; 2048];
            for pair in 0..15 {
                for packed in if pair % 2 == 0 { [false, true] } else { [true, false] } {
                    let root = tempfile::tempdir().unwrap();
                    let segment = root.path().join("segments/s_0000000000000001");
                    fs::create_dir_all(segment.join("columns")).unwrap();
                    let start = Instant::now();
                    if packed {
                        let mut writer = BufWriter::with_capacity(65536, File::create(segment.join("columns/data.bundle")).unwrap());
                        writer.write_all(b"LXPROBE1").unwrap();
                        let mut offset = 8u64;
                        let mut table = Vec::new();
                        for (name, bytes) in &files {
                            writer.write_all(bytes).unwrap();
                            table.push((name, offset, bytes.len() as u64, crc32fast::hash(bytes)));
                            offset += bytes.len() as u64;
                        }
                        let encoded = serde_json::to_vec(&table).unwrap();
                        writer.write_all(&encoded).unwrap();
                        writer.write_all(&(encoded.len() as u64).to_le_bytes()).unwrap();
                        writer.write_all(&crc32fast::hash(&encoded).to_le_bytes()).unwrap();
                        writer.flush().unwrap();
                    } else {
                        for (name, bytes) in &files {
                            fs::write(segment.join(name), bytes).unwrap();
                        }
                    }
                    durability::publish_catalog_after_trees([segment.as_path()], &root.path().join("catalog.json"), &catalog).unwrap();
                    let elapsed = start.elapsed();
                    println!("{}", json!({"kind":"artifact_sample", "rows":rows.len(), "pair":pair, "layout":if packed {"shared"} else {"split"}, "elapsed_ms":elapsed.as_secs_f64()*1000.0, "logical_artifact_bytes":files.values().map(Vec::len).sum::<usize>(), "artifact_files":if packed {1} else {files.len()}}));
                    assert_eq!(fs::read(root.path().join("catalog.json")).unwrap(), catalog);
                    if packed {
                        verify_bundle(&segment.join("columns/data.bundle"), &files);
                    } else {
                        for (name, bytes) in &files {
                            assert_eq!(fs::read(segment.join(name)).unwrap(), *bytes);
                        }
                    }
                }
            }
        }
    }
    // The existing coherent fixture is inserted below by the build script.
use alloy_consensus::Header;
use alloy_primitives::{Address, B256, Bloom, Bytes, keccak256};

use logex_types::{ExecutionAnchor, LogRow, Source};


struct Config {
    blocks: usize,
    warm_headers: usize,
    rows_per_block: usize,
    history_batch_blocks: usize,
    segment_rows: u64,
    repeats: usize,
    route: Option<bool>,
    checkpoint_each_block: bool,
    rich_headers: bool,
}

// SyncEngine's retained canonical-header window.
const RECENT_HEADER_WINDOW: usize = 8_192;

fn positive_env(name: &str, default: usize) -> usize {
    match std::env::var(name) {
        Ok(value) => value
            .parse::<usize>()
            .ok()
            .filter(|value| *value > 0)
            .unwrap_or_else(|| panic!("{name} must be a positive integer")),
        Err(std::env::VarError::NotPresent) => default,
        Err(error) => panic!("invalid {name}: {error}"),
    }
}

fn fill_header_fields(header: &mut Header, index: usize) {
    let hash = |tag: u8| {
        let mut seed = (index as u64).to_le_bytes().to_vec();
        seed.push(tag);
        keccak256(seed)
    };
    header.beneficiary = Address::from_slice(&hash(0).as_slice()[12..]);
    header.state_root = hash(1);
    header.transactions_root = hash(2);
    header.receipts_root = hash(3);
    header.mix_hash = hash(4);
    header.extra_data = Bytes::copy_from_slice(hash(5).as_slice());
    let mut bloom = [0u8; 256];
    for (part, chunk) in bloom.as_chunks_mut::<32>().0.iter_mut().enumerate() {
        chunk.copy_from_slice(hash(10 + part as u8).as_slice());
    }
    header.logs_bloom = Bloom::from(bloom);
    header.gas_used = 15_000_000 + index as u64;
    header.base_fee_per_gas = Some(1_000_000_000 + index as u64);
    header.withdrawals_root = Some(hash(20));
    header.blob_gas_used = Some(393_216);
    header.excess_blob_gas = Some(index as u64 * 131_072);
    header.parent_beacon_block_root = Some(hash(21));
    header.requests_hash = Some(hash(22));
}

fn fixture(config: &Config) -> (Vec<Header>, Vec<Vec<LogRow>>) {
    let mut headers = Vec::with_capacity(config.warm_headers + config.blocks);
    let mut blocks = Vec::with_capacity(config.blocks);
    let mut parent_hash = B256::ZERO;
    for index in 0..config.warm_headers + config.blocks {
        let mut header = Header {
            number: 15_000_000 + index as u64,
            parent_hash,
            timestamp: 1_700_000_000 + index as u64 * 12,
            gas_limit: 30_000_000,
            ..Default::default()
        };
        if config.rich_headers {
            fill_header_fields(&mut header, index);
        }
        let hash = header.hash_slow();
        parent_hash = hash;
        headers.push(header.clone());
        if index < config.warm_headers {
            continue;
        }
        let count = if (index - config.warm_headers + 1).is_multiple_of(16) {
            0
        } else {
            config.rows_per_block
        };
        let rows = (0..count)
            .map(|log| {
                let mut key = hash.to_vec();
                key.extend_from_slice(&(log as u64 / 2).to_le_bytes());
                let data = Bytes::copy_from_slice(keccak256(&key).as_slice());
                LogRow {
                    block_number: header.number,
                    block_hash: hash,
                    timestamp: header.timestamp,
                    tx_hash: keccak256(&key),
                    tx_index: u32::try_from(log / 2).unwrap(),
                    log_index: u32::try_from(log).unwrap(),
                    address: Address::repeat_byte((log % 251) as u8),
                    topic0: Some(keccak256("Transfer(address,address,uint256)")),
                    topic1: (log % 2 == 0).then_some(hash),
                    topic2: None,
                    topic3: None,
                    data_len: u32::try_from(data.len()).unwrap(),
                    data,
                    source: Source::Receipt,
                }
            })
            .collect();
        blocks.push(rows);
    }
    (headers, blocks)
}


}
